import React from "react";

export default function UploadForm({ file, onPickFile, onAnalyze, loading }) {
  return (
    <div style={styles.row}>
      <label style={styles.pick}>
        <input
          type="file"
          accept="video/*"
          onChange={(e) => onPickFile(e.target.files?.[0] || null)}
          style={{ display: "none" }}
          disabled={loading}
        />
        {file ? "Change Video" : "Choose Video"}
      </label>
      <div style={styles.meta}>{file ? `${file.name} (${Math.round(file.size / 1024 / 1024)} MB)` : "No file selected"}</div>
      <button onClick={onAnalyze} disabled={!file || loading} style={styles.button}>
        {loading ? "Processing…" : "Analyze"}
      </button>
    </div>
  );
}

const styles = {
  row: {
    display: "flex",
    gap: 12,
    alignItems: "center",
    flexWrap: "wrap",
  },
  pick: {
    padding: "10px 12px",
    borderRadius: 10,
    border: "1px solid rgba(255,255,255,0.12)",
    cursor: "pointer",
    background: "rgba(255,255,255,0.06)",
    color: "white",
  },
  meta: {
    color: "#cbd5e1",
    flex: 1,
    minWidth: 240,
  },
  button: {
    padding: "10px 14px",
    borderRadius: 10,
    border: "none",
    background: "#ef4444",
    color: "white",
    cursor: "pointer",
    fontWeight: 800,
  },
};
